const inputData = $input.item.json;
let rawText = inputData.text || inputData.output || (typeof inputData === 'string' ? inputData : JSON.stringify(inputData));
const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = null;
try { parsed = JSON.parse(cleaned); } catch (e) { parsed = null; }

let loopContext = {};
try { loopContext = $('Loop Over Items').item.json; } catch (err) { loopContext = {}; }

const ideaId = loopContext.idea_id || inputData.idea_id || ("IDEA-" + Date.now());

const source = {
  idea_id: ideaId,
  category_id: loopContext.category_id || "",
  category_name: loopContext.category_name || "",
  category_slug: loopContext.category_slug || "",
  subcategory_id: loopContext.subcategory_id || "",
  subcategory_name: loopContext.subcategory_name || "",
  subcategory_slug: loopContext.subcategory_slug || "",
  focus_keyword: loopContext.focus_keyword || "",
  additional_keyword_1: loopContext.additional_keyword_1 || "",
  additional_keyword_2: loopContext.additional_keyword_2 || "",
  business_description: loopContext.business_description || "",
  collection_id: loopContext.collection_id || ""
};

// If parsing failed or required fields missing, mark for retry — never fabricate biased placeholder content.
if (!parsed || !parsed.title || !parsed.summary) {
  return { json: { ...source, status: "needs_retry" } };
}

const str = (v) => (v === undefined || v === null) ? "" : String(v);
const arr = (v) => Array.isArray(v) ? JSON.stringify(v) : (typeof v === 'string' ? v : JSON.stringify(v || []));
const trendScore = parseInt(parsed.trend_score, 10) || 70;
const tier = parsed.tier || (trendScore >= 88 ? "premium" : "free");

return {
  json: {
    ...source,
    title: str(parsed.title),
    slug: str(parsed.slug),
    seo_title: str(parsed.seo_title),
    meta_description: str(parsed.meta_description),
    summary: str(parsed.summary),
    market_opportunity: str(parsed.market_opportunity),
    target_customer: str(parsed.target_customer),
    how_you_make_money: str(parsed.how_you_make_money),
    startup_cost: str(parsed.startup_cost),
    income_potential: str(parsed.income_potential),
    competition_edge: str(parsed.competition_edge),
    getting_started_steps: arr(parsed.getting_started_steps),
    tools_needed: arr(parsed.tools_needed),
    time_to_first_customer: str(parsed.time_to_first_customer),
    faq_json: arr(parsed.faq_json),
    tags: arr(parsed.tags),
    pros_json: arr(parsed.pros_json),
    cons_json: arr(parsed.cons_json),
    verdict: str(parsed.verdict),
    external_links: arr(parsed.external_links),
    internal_link_anchors: arr(parsed.internal_link_anchors),
    trend_score: trendScore,
    tier: tier,
    status: "completed"
  }
};
